(parseFloat(zs.borderLeftWidth) || 0) + (parseFloat(zs.borderRightWidth) || 0);
var desiredBox = 44 * rootSize * ((self._screenSizePct || 100) / 100);
var baseW = self._videoDims().w;
var deckRight = main ? this._pletinaAlLado(main, ms, rootSize, dpr, chrome, desiredBox, baseW) : false;
var available = main ? main.clientWidth : document.documentElement.clientWidth;
if (main && available <= 0) return;
if (ms) available -= (parseFloat(ms.paddingLeft) || 0) + (parseFloat(ms.paddingRight) || 0);
if (deckRight) available -= (17 + 1.25) * rootSize;
var maxScale = Math.floor(Math.max(0, available - chrome) * dpr / baseW);
