item('ctx-reset', function () { if (self.doReset) self.doReset(); });
item('ctx-export-z80', function () { if (self.doExportZ80) self.doExportZ80(); });
item('ctx-export-szx', function () { if (self.doExportSzx) self.doExportSzx(); });
