if (typeof TapeSampled === 'undefined') {
this.setStatus(T.t('El módulo de cintas muestreadas (js/tape-sampled.js) no está disponible.'), true);
fin(false);
return;
}
this.setStatus(T.t('Descomprimiendo la grabación de {0}…', name));
this._audioTurno = (this._audioTurno | 0) + 1;
var turno = this._audioTurno;
TapeSampled.resolve(tape).then(function (lista) {
if (turno !== self._audioTurno) { fin(false); return; }
if (keepMachine) { fin(self.swapTape(lista, name)); return; }
self.insertTapeWithMode(lista, name);
fin(true);
}, function (err) {
if (turno !== self._audioTurno) { fin(false); return; }
self.setStatus(T.t('No se pudo leer la cinta {0}: {1}', name, (err && err.message) || err), true);
fin(false);
});
