if (this._digitizer) {
var tope = this._fmtSeg(this._digitizer.maxSeconds());
info = T.t('Digitalizando: {0} (como mucho {1})', Util.padNum(this._fmtSeg(this._digitizer.seconds()), tope.length), tope);
}
if (block.textContent !== info) block.textContent = info;
