var resumen = !tape ? (grabando ? T.t('Grabando…') : vacia)
: (els.label ? els.label.textContent : '') + ' · ' + (els.counter ? els.counter.textContent : '') + ' · ' + estado;
if (els.headInfo.textContent !== resumen) els.headInfo.textContent = resumen;
