a.tape.position = a.position;
sp._lastTrapPos = a.position;
this.lastTape = a.lastTape || { tape: a.tape, name: a.name };
this._tapeFileName = a.name || '';
this._deckLabelTape = undefined;
this._recordingsAside = null;
