if (!beta) {
this.setStatus(T.t('La Beta Disk no está disponible (falta js/betadisk.js).'), true);
return;
}
var trd;
try {
trd = BetaDisk.diskImage(bytes, lower);
} catch (err) {
this.setStatus(T.t('Error al leer el disco «{0}»: {1}', name, err.message), true);
return;
}
