this._pendingDisk = { bytes: bytes, lower: lower, name: name };
this.setStatus(T.t('Para usar discos TR-DOS falta su ROM, que no viene incluida: carga UNA vez tu ' +
'fichero trdos.rom (16 KB) en Ajustes → Periféricos → «Cambiar…» (o con «Elegir fichero…») ' +
'y este disco arrancará solo.'), true);
