for (a = 0; a < 65536; a++) {
if (!prof[a]) continue;
var lo = 0, hi = idx.length - 1, k = -1;
while (lo <= hi) { var mid = (lo + hi) >> 1; if (idx[mid] <= a) { k = mid; lo = mid + 1; } else hi = mid - 1; }
if (k >= 0 && etiquetas[k].tope) k = -1;
var ac = acum[k] || (acum[k] = { t: 0, k: k });
ac.t += prof[a];
}
var filas = Object.keys(acum).map(function (kk) { return acum[kk]; })
.sort(function (x, y) { return y.t - x.t; }).slice(0, 14);
