var llamadas = (et && hits) ? hits[et.addr] : 0;
var row = self.devtools._el('button', 'prof-row');
row.type = 'button';
row.setAttribute('style', '--p:' + (e.t / tMax * 100).toFixed(1) + '%');
row.innerHTML = '<span class="prof-pct">' + (e.t / total * 100).toFixed(1).replace('.', coma) + '%</span>' +
'<span class="prof-addr">' + (et ? h4(et.addr) : '—') + '</span>' +
'<span class="prof-hits">' + (llamadas ? veces(llamadas) : '') + '</span>' +
'<span class="prof-ins"' + (et ? ' translate="no"' : '') + '>' + esc(et ? et.name : T.t('(sin etiqueta)')) +
(llamadas ? ' · ' + miles(Math.round(e.t / llamadas)) + ' T/' + T.t('llamada') : '') + '</span>';
row.setAttribute('data-tooltip', T.t('{0} t-states', miles(e.t)));
if (et) row.addEventListener('click', function () { dt.gotoAddr(et.addr); });
dt.profRoutines.appendChild(row);
