var bytes = 0;
rec.ondataavailable = function (e) {
if (e.data && e.data.size) { chunks.push(e.data); bytes += e.data.size; self.mp4Rec && (self.mp4Rec.bytes = bytes); }
};
rec.onstop = function () { self._mp4Guardar(stream, mime, chunks); };
