texto += ' · ' + T.t('retardo de {0} fotogramas', net.retardo) + ' (' + Math.round(net.retardo * (this.msPerFrame || 20)) + ' ms)';
if (net.esperaPct >= 0.05) texto += ' · ' + T.t('esperas {0} %', net.esperaPct.toFixed(1).replace('.', ','));
if (net.ls && net.ls.desincronias) texto += ' · ' + T.t('{0} realineados', net.ls.desincronias);
if (net.vozAjena) texto += ' · ' + T.t('el otro jugador habla');
if (net.soloMirar) texto += ' · ' + T.t('solo miras');
if (net.miraAjeno) texto += ' · ' + T.t('el otro jugador solo mira');
if (net.esperandoDesde && net.avisoEspera) texto += ' · ' + T.t('esperando al otro jugador');
break;
